const crypto=require('crypto');const {config,createRecords}=require('../_lib/airtable');const {jsonBody,hashPassword,setSessionCookie,sessionMinutes,users,audit}=require('../_lib/auth');
module.exports=async function handler(req,res){if(req.method!=='POST')return res.status(405).json({ok:false});try{if((await users()).length)return res.status(409).json({ok:false,error:'BOOTSTRAP_ALREADY_DONE'});const b=jsonBody(req),username=String(b.username||'').trim(),displayName=String(b.displayName||'').trim(),password=String(b.password||'');if(!username||!displayName)return res.status(400).json({ok:false,error:'FIELDS_REQUIRED'});const p=hashPassword(password),id=`user_${crypto.randomUUID()}`,c=config();await createRecords(c.users,[{'User ID':id,'Username':username,'Display Name':displayName,'Role ID':'admin','Active':true,'Password Salt':p.salt,'Password Hash':p.hash,'Password Iterations':p.iterations}]);await audit('security.bootstrap','Création du premier administrateur',id);setSessionCookie(res,id,await sessionMinutes());res.status(201).json({ok:true,userId:id})}catch(e){console.error(e);res.status(500).json({ok:false,error:'BOOTSTRAP_FAILED',message:e.message})}}
